package main

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

// Explicitly opt-in diagnostic event stream; never changes rendering decisions,
// delays workers, records document contents, or creates parent directories.
// The caller supplies an absolute path in its disposable qualification report.
const pdfTraceMaxBytes int64 = 4 * 1024 * 1024

var pdfTraceMutex sync.Mutex
var pdfTraceSequence uint64

type PDFTraceEvent struct {
	Schema      int            `json:"schema"`
	Sequence    uint64         `json:"sequence"`
	UTC         string         `json:"utc"`
	HostPID     int            `json:"host_pid"`
	Event       string         `json:"event"`
	Generation  uint64         `json:"generation"`
	InputPath   string         `json:"input_path"`
	OutputPath  string         `json:"output_path"`
	RendererPID int            `json:"renderer_pid"`
	Failed      bool           `json:"failed"`
	State       *PDFTraceState `json:"state,omitempty"`
}
type PDFTraceState struct {
	Generation       uint64 `json:"generation"`
	WorkerGeneration uint64 `json:"worker_generation"`
	Active           bool   `json:"active"`
	Busy             bool   `json:"busy"`
	Pending          bool   `json:"pending"`
	Path             string `json:"path"`
}

func recordPDFTrace(event PDFTraceEvent) { _ = appendPDFTrace(os.Getenv("DCM_PDF_TRACE"), event) }
func appendPDFTrace(path string, event PDFTraceEvent) error {
	if strings.TrimSpace(path) == "" {
		return nil
	}
	if !filepath.IsAbs(path) {
		return errors.New("PDF trace requires an absolute path")
	}
	pdfTraceMutex.Lock()
	defer pdfTraceMutex.Unlock()
	f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return err
	}
	defer f.Close()
	info, err := f.Stat()
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() || info.Size() >= pdfTraceMaxBytes {
		return errors.New("PDF trace is nonregular or full")
	}
	pdfTraceSequence++
	event.Schema = 1
	event.Sequence = pdfTraceSequence
	event.UTC = time.Now().UTC().Format(time.RFC3339Nano)
	event.HostPID = os.Getpid()
	data, err := json.Marshal(event)
	if err != nil {
		return err
	}
	if info.Size()+int64(len(data))+1 > pdfTraceMaxBytes {
		return errors.New("PDF trace size limit")
	}
	_, err = f.Write(append(data, '\n'))
	return err
}

package main

import (
	"bufio"
	"encoding/json"
	"os"
	"path/filepath"
	"sync"
	"testing"
)

func TestDCM34PDFTraceDisabled(t *testing.T) {
	t.Setenv("DCM_PDF_TRACE", "")
	if err := appendPDFTrace("", PDFTraceEvent{Event: "worker-started", Generation: 7}); err != nil {
		t.Fatal(err)
	}
	recordPDFTrace(PDFTraceEvent{Event: "worker-started", Generation: 7})
}
func TestDCM34PDFTraceErrors(t *testing.T) {
	for _, p := range []string{"relative.jsonl", filepath.Join(t.TempDir(), "missing", "trace.jsonl")} {
		if err := appendPDFTrace(p, PDFTraceEvent{Event: "worker-started"}); err == nil {
			t.Fatalf("expected trace error for %q", p)
		}
	}
	// Diagnostic failures must never propagate into the preview operation.
	t.Setenv("DCM_PDF_TRACE", t.TempDir())
	recordPDFTrace(PDFTraceEvent{Event: "worker-finished", Generation: 7})
}
func TestDCM34PDFTraceConcurrentRecords(t *testing.T) {
	path := filepath.Join(t.TempDir(), "trace.jsonl")
	const n = 40
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(g uint64) {
			defer wg.Done()
			if err := appendPDFTrace(path, PDFTraceEvent{Event: "worker-finished", Generation: g, InputPath: "synthetic.pdf", RendererPID: 123, Failed: g%2 == 0}); err != nil {
				t.Error(err)
			}
		}(uint64(i + 1))
	}
	wg.Wait()
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	count := 0
	var previous uint64
	for scanner.Scan() {
		var event PDFTraceEvent
		if err := json.Unmarshal(scanner.Bytes(), &event); err != nil {
			t.Fatal(err)
		}
		if event.Sequence <= previous || event.HostPID != os.Getpid() || event.UTC == "" || event.Schema != 1 || event.Generation == 0 || event.Event != "worker-finished" {
			t.Fatalf("invalid event %+v", event)
		}
		previous = event.Sequence
		count++
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	if count != n {
		t.Fatalf("records=%d", count)
	}
}
func TestDCM34PDFTraceBounded(t *testing.T) {
	path := filepath.Join(t.TempDir(), "full.jsonl")
	f, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	if err = f.Truncate(pdfTraceMaxBytes); err != nil {
		t.Fatal(err)
	}
	f.Close()
	if err := appendPDFTrace(path, PDFTraceEvent{Event: "worker-finished"}); err == nil {
		t.Fatal("trace size cap missing")
	}
	s, _ := os.Stat(path)
	if s.Size() != pdfTraceMaxBytes {
		t.Fatal("full trace was modified")
	}
}

# Pure event contract used by the real-app harness and the tooling gate.
# No timing sleeps, process suspension, injected completions or fake renderer.
function Assert-DcmPdfInFlightTrace($Events,[long]$Generation,[bool]$Failed,[long]$NewGeneration=0){
 $rows=@($Events);if(-not $rows.Count){throw 'INFLIGHT_TRACE: empty evidence'}
 $last=[long]0;$hostId=[long]$rows[0].host_pid
 foreach($e in $rows){if($e.schema -ne 1 -or $e.host_pid -ne $hostId -or $e.sequence -le $last){throw 'INFLIGHT_TRACE: invalid stream identity/order'};$last=[long]$e.sequence}
 $old=@($rows|Where-Object {$_.generation -eq $Generation})
 $start=@($old|Where-Object {$_.event -ceq 'worker-started'});$finish=@($old|Where-Object {$_.event -ceq 'worker-finished'});$discard=@($old|Where-Object {$_.event -ceq 'result-discarded'});$stop=@($old|Where-Object {$_.event -ceq 'selection-stopped'})
 if($start.Count -ne 1 -or $finish.Count -ne 1 -or $discard.Count -ne 1 -or $stop.Count -ne 1){throw 'INFLIGHT_TRACE: missing/duplicate lifecycle event'}
 $s=$start[0];$f=$finish[0];$d=$discard[0];$x=$stop[0]
 if($s.renderer_pid -le 0 -or $f.renderer_pid -ne $s.renderer_pid -or $f.input_path -cne $s.input_path -or $d.input_path -cne $s.input_path -or $f.output_path -cne $s.output_path -or $d.output_path -cne $s.output_path){throw 'INFLIGHT_TRACE: request or child identity changed'}
 if(-not ($s.sequence -lt $x.sequence -and $x.sequence -lt $f.sequence -and $f.sequence -lt $d.sequence)){throw 'INFLIGHT_TRACE: renderer was not observed spanning the selection change'}
 if($f.failed -ne $Failed -or $d.failed -ne $Failed){throw 'INFLIGHT_TRACE: unexpected renderer outcome'}
 if(@($old|Where-Object {$_.event -cin @('result-applied','result-unavailable')}).Count){throw 'INFLIGHT_TRACE: obsolete result reached presenter'}
 if($NewGeneration -gt 0){
  $n=@($rows|Where-Object {$_.generation -eq $NewGeneration -and $_.event -ceq 'worker-started'});$a=@($rows|Where-Object {$_.generation -eq $NewGeneration -and $_.event -ceq 'result-applied'})
  if($n.Count -ne 1 -or $a.Count -ne 1 -or $n[0].sequence -ge $f.sequence -or $a[0].sequence -le $d.sequence -or $n[0].input_path -cne $s.input_path){throw 'INFLIGHT_TRACE: same-file replacement overlap not proved'}
  if(-not $d.state.active -or -not $d.state.busy -or $d.state.pending -or $d.state.worker_generation -ne $NewGeneration -or $d.state.generation -ne $NewGeneration -or $d.state.path -cne $s.input_path){throw 'INFLIGHT_TRACE: stale completion altered newer worker'}
 }else{
  if($d.state.active -or $d.state.busy -or $d.state.pending -or $d.state.worker_generation -ne 0 -or $d.state.path -cne ''){throw 'INFLIGHT_TRACE: stale completion altered stopped PDF state'}
 }
 return [pscustomobject]@{generation=$Generation;renderer_pid=$s.renderer_pid;input_path=$s.input_path;output_path=$s.output_path;started_sequence=$s.sequence;stopped_sequence=$x.sequence;finished_sequence=$f.sequence;discarded_sequence=$d.sequence;replacement_generation=$NewGeneration;failed=$Failed;passed=$true}
}

function Read-DcmPdfTrace {
 if(-not(Test-Path -LiteralPath $tracePath)){return @()}
 $stream=[IO.File]::Open($tracePath,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
 $reader=New-Object IO.StreamReader($stream,[Text.Encoding]::UTF8)
